#include "jobs-token-budget.h"
#include "jobs-prefix-cache.h"
#include <cassert>
#include <cmath>
#include <cstdio>
#include <vector>
#include <string>
int main(int argc,char**argv){assert(argc==2);llama_log_set([](ggml_log_level,const char*,void*){},nullptr);llama_backend_init();auto mp=llama_model_default_params();auto*m=llama_model_load_from_file(argv[1],mp);assert(m);
 std::string sys="Use actual tool results and keep project permissions unchanged. ";for(int i=0;i<3;i++)sys+=sys;std::string note="Application feedback (not a new user request or permission change; verify facts against tool results): ";for(int i=0;i<4;i++)note+="Completed historical steps must not restart. Verify current file state or finish. ";
 std::vector<std::string>r={"system","user","assistant","user","user"},t={sys,"Check file","read call","File result: Verification Ubuntu",note};auto old=jobs_prompt_tokens(m,r,t);auto alt=r;alt.back()="assistant";size_t point=jobs_feedback_checkpoint(m,r,t,4,old);assert(point==jobs_prefix_cache::common(old,jobs_prompt_tokens(m,alt,t)));assert(jobs_feedback_checkpoint(m,r,t,-1,old)==0);assert(jobs_feedback_checkpoint(m,r,t,99,old)==0);assert(jobs_feedback_checkpoint(m,r,t,2,old)==0);size_t base=jobs_prefix_cache::common(jobs_prompt_tokens(m,{"system","user"},{sys,"A-boundary"}),jobs_prompt_tokens(m,{"system","user"},{sys,"B-boundary"}));
 auto nr=r,nt=t;nr.back()="assistant";nt.back()="Another read call";nr.push_back("user");nt.push_back("New result: same file");nr.push_back("user");nt.push_back(note+" Two steps done.");auto next=jobs_prompt_tokens(m,nr,nt);assert(base<point&&point<=jobs_prefix_cache::common(old,next));
 auto eval=[&](bool improved){auto cp=llama_context_default_params();cp.n_ctx=4096;cp.n_batch=2048;cp.n_threads=2;cp.n_threads_batch=2;auto*c=llama_init_from_model(m,cp);assert(c);jobs_prefix_cache cache;assert(cache.begin(c,old,"chat","rights")==0);size_t tail=improved?point:old.size()-64;
  size_t done=0;while(done<old.size()){size_t end=std::min(done+256,old.size());for(auto boundary:{base,tail})if(boundary>done&&boundary<end)end=boundary;assert(llama_decode(c,llama_batch_get_one(old.data()+done,end-done))==0);cache.append(old.data()+done,end-done);done=end;if(done==base)assert(cache.capture(c,cache.base));if(done==tail)assert(cache.capture(c,cache.tail));}
  size_t reuse=cache.begin(c,next,"chat","rights",false);assert(reuse==(improved?point:base));printf("%s reused=%zu input=%zu reason=%s\n",improved?"before-feedback":"old-tail-64",reuse,next.size(),cache.status.c_str());assert(llama_decode(c,llama_batch_get_one(next.data()+reuse,next.size()-reuse))==0);cache.append(next.data()+reuse,next.size()-reuse);int n=llama_vocab_n_tokens(llama_model_get_vocab(m));auto*p=llama_get_logits_ith(c,-1);std::vector<float>warm(p,p+n);
  cache.invalidate(c);assert(llama_decode(c,llama_batch_get_one(next.data(),next.size()))==0);auto*cold=llama_get_logits_ith(c,-1);float diff=0;for(int i=0;i<n;i++)diff=std::max(diff,std::abs(cold[i]-warm[i]));printf("max-logit-diff=%.8f\n",diff);assert(diff<.001f);llama_free(c);};eval(false);eval(true);llama_model_free(m);puts("PASS snapshot restoration with trimming disabled; logits match cold next input");}
